// Guards the VENDORED design tokens at `src/app/tokens.css`.
//
// Implements: AGENTS.md Rule 5 (every colour comes from the generated palette or
// it does not ship) and §2 Rule 10 (accessibility — the tokens carry the
// contrast-solved text and accent roles).
//
// WHY A TEST IS NEEDED HERE. `tokens.css` is GENERATED by
// `@buddysaradhi/design-system` and was vendored into this standalone repo
// because `src/app/globals.css` used to import it via
// `../../../../packages/design-system/tokens.css` — a path that only resolves
// inside the monorepo. That import broke `next build` outright, and `tsc` is
// structurally unable to catch it: a CSS `@import` is not a module import, so
// every typecheck and test in the monorepo passed while the standalone build
// was broken.
//
// Vendoring fixes the build but introduces the opposite risk: a generated
// artifact can drift from its source of truth, and nothing would notice. The
// cross-repo re-sync itself cannot be checked from inside this repository (the
// design system does not exist here). What CAN be checked, and is checked here,
// is that the vendored copy is INTACT and SELF-CONSISTENT — that it is the real
// generated file, not a truncated paste, and that the roles the product depends
// on are actually present.
//
// This is a drift/tamper guard, NOT a proof of cross-repo synchronisation. The
// re-sync procedure is documented in the file's own header. Do not describe this
// suite as "tokens are up to date" — it cannot know that.

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const TOKENS_PATH = resolve(import.meta.dirname, "../src/app/tokens.css");
const tokens = readFileSync(TOKENS_PATH, "utf8");

describe("vendored design tokens are intact", () => {
  it("carries its provenance header", () => {
    // Without this the file is indistinguishable from a hand-written CSS file,
    // and the re-sync instructions in it are the only thing telling a future
    // maintainer NOT to edit it.
    expect(tokens).toContain("GENERATED by @buddysaradhi/design-system");
    expect(tokens).toContain("DO NOT EDIT");
    // The standalone-specific instructions, not the monorepo originals.
    expect(tokens).toContain("WHY THIS FILE IS VENDORED HERE");
    expect(tokens).toContain("HOW TO RE-SYNC");
  });

  it("is not a truncated copy", () => {
    // A partial paste is the realistic failure mode of a manual vendoring step,
    // and it would be invisible until a component referenced a missing role.
    expect(tokens.length).toBeGreaterThan(50_000);
    // The generated file opens :root and closes it; an unbalanced block means
    // the copy was cut mid-file.
    const open = (tokens.match(/\{/g) ?? []).length;
    const close = (tokens.match(/\}/g) ?? []).length;
    expect(open).toBe(close);
    expect(tokens.trimEnd().endsWith("}")).toBe(true);
  });

  it("defines the three material modes", () => {
    // 13_UI_Guidelines / overhaul-plan.md §2: Minimal, Acrylic, Liquid Glass.
    for (const mode of ["minimal", "acrylic", "liquid-glass"]) {
      expect(tokens.toLowerCase()).toContain(mode);
    }
  });

  it("defines the semantic roles the product actually reads", () => {
    // These are the custom properties components reference. A token file that
    // compiles but is missing these renders the page unstyled — silently, since
    // `var(--missing)` has no fallback in a strict cascade.
    for (const role of [
      "--canvas",
      "--text-primary",
      "--text-secondary",
      "--text-muted",
      "--accent-primary",
      "--accent-text",
      "--success",
      "--warning",
      "--danger",
      "--info",
    ]) {
      expect(tokens).toContain(role);
    }
  });

  it("carries a surface tint per palette, not a single hard-coded canvas", () => {
    // Rule 5: colour is GENERATED from the palette library. One `--canvas` for
    // the whole file would mean a single hand-picked colour had been pasted in.
    const canvasCount = (tokens.match(/--canvas\s*:/g) ?? []).length;
    expect(canvasCount).toBeGreaterThan(1);
  });
});

describe("the app imports the LOCAL tokens path", () => {
  it("globals.css does not escape the app directory", () => {
    // The exact defect this whole arrangement exists to prevent. Assert on the
    // import line itself so the test fails the moment someone reintroduces a
    // monorepo-relative path, regardless of whether the build is run.
    const globals = readFileSync(
      resolve(import.meta.dirname, "../src/app/globals.css"),
      "utf8"
    );
    const adminCss = readFileSync(
      resolve(import.meta.dirname, "../src/app/admin/globals-admin.css"),
      "utf8"
    );
    expect(globals).toContain('@import "./tokens.css"');
    expect(adminCss).toContain('@import "../tokens.css"');
    expect(globals).not.toMatch(/\.\.\/\.\.\/packages\//);
    expect(adminCss).not.toMatch(/\.\.\/\.\.\/\.\.\/packages\//);
  });
});